module axis_master_good (
  input  wire        ACLK,
  input  wire        ARESETn,
  output reg         TVALID,
  input  wire        TREADY,
  output reg  [31:0] TDATA,
  output reg  [ 3:0] TKEEP,
  output reg         TLAST
);
  typedef enum logic [1:0] { IDLE, LOAD, SEND } state_t;
  state_t state;

  always @(posedge ACLK or negedge ARESETn) begin
    if (!ARESETn) begin
      TVALID <= 1'b0;
      TDATA  <= 32'b0;
      TKEEP  <= 4'b0;
      TLAST  <= 1'b0;
      state  <= IDLE;
    end else begin
      case (state)
        IDLE: begin
          if (src_valid) begin
            TDATA  <= src_data;
            TKEEP  <= src_keep;
            TLAST  <= src_last;
            TVALID <= 1'b1;
            state  <= SEND;
          end
        end
        SEND: begin
          if (TVALID & TREADY) begin
            if (src_valid) begin
              TDATA <= src_data;
              TKEEP <= src_keep;
              TLAST <= src_last;
            end else begin
              TVALID <= 1'b0;
              state  <= IDLE;
            end
          end
        end
      endcase
    end
  end
endmodule
